// /frontend-react/src/components/AppointmentFlow.js (Updated Needs Selection)

import React, { useState } from 'react';
import HeaderBar from './HeaderBar';

const FlowButton = ({ label, emoji, isBlinking, onClick, isEasyMode, primaryColor = '#007bff' }) => (
    <button 
        onClick={onClick}
        style={{
            padding: '20px 10px', 
            margin: '10px 5px', 
            border: `4px solid ${isBlinking ? primaryColor : '#ccc'}`,
            backgroundColor: isBlinking ? '#ffffcc' : 'white',
            fontWeight: 'bold',
            fontSize: isEasyMode ? '24px' : '18px', 
            animation: isBlinking ? 'pulse 1.5s infinite' : 'none',
            cursor: 'pointer',
            transition: 'all 0.3s',
            borderRadius: '10px',
            color: '#333',
            width: '30%', // Keep width flexible
            minWidth: '100px',
            boxSizing: 'border-box',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
        }}
    >
        <span role="img" aria-label={label} style={{fontSize: isEasyMode ? '50px' : '30px', display: 'block', marginBottom: '5px'}}>{emoji}</span>
        {label}
    </button>
);

function AppointmentFlow({ isEasyMode, appointment, goToTransportStatus, goToMedicalDashboard }) {
    const [step, setStep] = useState(0); 
    const [needsTransport, setNeedsTransport] = useState(null); 
    const [transportNeed, setTransportNeed] = useState(null); 

    const sendTransportData = () => {
        console.log('--- Data Sent: TRANSPORT BOOKED ---', { transportNeed });
        setStep(3); 
        setTimeout(goToTransportStatus, 2000); 
    };
    
    const sendNoTransportData = () => {
        console.log('--- Data Sent: NO TRANSPORT NEEDED, APPOINTMENT CONFIRMED ---');
        setStep(3); 
        setTimeout(goToMedicalDashboard, 2000); 
    };

    const getBlinkingStyle = (currentStep) => ({
        border: `5px solid ${step === currentStep ? '#FFC107' : '#ddd'}`, 
        backgroundColor: step === currentStep ? '#FFFBEA' : '#ffffff',
        boxShadow: step === currentStep ? '0 0 15px rgba(255,193,7,0.8)' : '0 2px 5px rgba(0,0,0,0.1)',
        animation: step === currentStep ? 'pulse 1.5s infinite' : 'none', 
    });

    // --- TRANSPORT OPTIONS DEFINITION ---
    const transportOptions = [
        { key: 'bedridden', label: 'Bed', emoji: '🛏️' },
        { key: 'wheelchair', label: 'Chair', emoji: '♿' },
        { key: 'slow', label: 'Slow', emoji: '🚶' },
        { key: 'general', label: 'General', emoji: '👤' }, // New: No specialized vehicle needed
        { key: 'other', label: 'Other', emoji: '❓' },   // New: For custom text input
    ];

    return (
        <div style={{ padding: '0 20px 20px 20px', textAlign: 'center' }}>
            <HeaderBar title="Appointment Flow" onBackClick={goToMedicalDashboard} isEasyMode={isEasyMode}/>
            
            {/* 1. Date/Time Area (Skipped for brevity) */}
            {/* ... */}
            
            {/* 2. Do you need transport? (Skipped for brevity) */}
            {/* ... */}
            
            {/* 3. Choose Needs (FIXED: 5 OPTIONS) */}
            {step >= 2 && needsTransport && (
                <div style={{...getBlinkingStyle(2), padding: '20px', borderRadius: '15px'}}>
                    <h3 style={{fontSize: isEasyMode ? '32px' : '20px', margin: '0 0 15px 0', color: '#555'}}>
                        Select your need:
                    </h3>
                    
                    {/* The needs section is now a responsive grid */}
                    <div style={{ 
                        display: 'flex', 
                        flexWrap: 'wrap', 
                        justifyContent: 'center', // Center content slightly better
                        gap: '5px' // Small gap between items
                    }}>
                        {transportOptions.map(option => (
                            <FlowButton
                                key={option.key}
                                label={option.label}
                                emoji={option.emoji}
                                isBlinking={step === 2 && transportNeed !== option.key}
                                isEasyMode={isEasyMode}
                                onClick={() => setTransportNeed(option.key)}
                                primaryColor={option.key === 'other' ? 'purple' : '#1A73E8'}
                            />
                        ))}
                    </div>
                    
                    {/* Add a simple text input/note for the 'Other' option */}
                    {transportNeed === 'other' && (
                        <div style={{marginTop: '15px', padding: '10px', border: '1px dashed gray', borderRadius: '5px'}}>
                             <p style={{fontSize: isEasyMode ? '20px' : '14px', margin: 0}}>
                                **NOTE:** In a final app, this would open a page for voice or text input for unique needs.
                             </p>
                        </div>
                    )}

                    {transportNeed && (
                        <button
                            onClick={sendTransportData}
                            style={{ padding: '15px 40px', fontSize: isEasyMode ? '30px' : '18px', backgroundColor: 'green', color: 'white', border: 'none', borderRadius: '10px', marginTop: '20px', fontWeight: 'bold'}}
                        >
                            Confirm & Book ✅
                        </button>
                    )}
                </div>
            )}
            
            {/* 4. Final State (Skipped for brevity) */}
            {/* ... */}
            
            <style jsx>{`
                @keyframes pulse {
                    0% { transform: scale(1); opacity: 1; }
                    50% { transform: scale(1.01); opacity: 0.8; }
                    100% { transform: scale(1); opacity: 1; }
                }
            `}</style>
        </div>
    );
}

export default AppointmentFlow;
